import{_ as a,C as i,o as s,c as l,j as t,a as r,E as n,ag as d}from"./chunks/framework.CVL0Hjzp.js";const w=JSON.parse('{"title":"Shell","description":"","frontmatter":{},"headers":[],"relativePath":"features/shell.md","filePath":"features/shell.md","lastUpdated":1780006646000}'),c={name:"features/shell.md"};function h(p,e,m,u,g,f){const o=i("ThemeImage");return s(),l("div",null,[e[0]||(e[0]=t("h1",{id:"shell",tabindex:"-1"},[r("Shell "),t("a",{class:"header-anchor",href:"#shell","aria-label":'Permalink to "Shell"'},"​")],-1)),e[1]||(e[1]=t("p",null,"The Shell widget is an interactive ADB shell tied to one tile. Each tile owns its own channel — opening two Shell tiles gives you two independent sessions, with separate working directories and history.",-1)),n(o,{"src-dark":"/img/features/shell-default.png","src-light":"/img/features/shell-default-light.png",alt:"Shell tile"}),e[2]||(e[2]=d('<h2 id="running-commands" tabindex="-1">Running commands <a class="header-anchor" href="#running-commands" aria-label="Permalink to &quot;Running commands&quot;">​</a></h2><p>Type a command at the prompt and hit <code>Enter</code>. The output streams into the scrollback as it arrives, the same way <code>adb shell</code> would render it in a terminal.</p><p>The shell is a regular interactive <code>sh</code> channel on the device, so anything the device&#39;s shell understands works — pipes, <code>grep</code>, <code>find</code>, multi-line commands, etc. There is no remote <code>bash</code> unless your device ships one.</p><h2 id="history" tabindex="-1">History <a class="header-anchor" href="#history" aria-label="Permalink to &quot;History&quot;">​</a></h2><ul><li><code>↑</code> / <code>↓</code> walks history backwards / forwards.</li><li>History is per-tile and persists across reloads.</li><li><code>Ctrl+L</code> clears the visible scrollback (history is preserved).</li></ul><h2 id="working-directory" tabindex="-1">Working directory <a class="header-anchor" href="#working-directory" aria-label="Permalink to &quot;Working directory&quot;">​</a></h2><p>The first prompt drops you in the device&#39;s home (commonly <code>/sdcard</code>). Use <code>cd</code> like normal — the prompt updates to reflect the new location, but only when the <code>cd</code> actually succeeds on-device (<code>cd /no/such/dir</code> leaves the prompt where it was). The default starting path is configurable in the per-widget settings modal (the cog in the header).</p><h2 id="dragging-in-a-path" tabindex="-1">Dragging in a path <a class="header-anchor" href="#dragging-in-a-path" aria-label="Permalink to &quot;Dragging in a path&quot;">​</a></h2><p>Drag a file row from the <a href="./files">Files</a> widget anywhere into the terminal area to paste its device-side path at the prompt caret. Useful for piping a path into <code>cat</code>, <code>ls</code>, <code>md5sum</code>, etc. without retyping. The file itself stays on the device — Files only triggers a Pull-to-laptop download when the drop lands outside the app.</p><h2 id="tab-completion" tabindex="-1">Tab completion <a class="header-anchor" href="#tab-completion" aria-label="Permalink to &quot;Tab completion&quot;">​</a></h2><p>Press <code>Tab</code> to complete the path component you&#39;re typing against the device&#39;s filesystem. On the simulator, completion runs against the in-memory fake FS; on a real device, the widget side-channels a <code>ls -1 -p -A &lt;dir&gt;</code> over a separate ADB shell subprocess, then:</p><ul><li>A single match extends the word in place (with a trailing <code>/</code> for directories so you can keep tabbing into the subtree).</li><li>Multiple matches extend to the longest common prefix and print the candidates inline.</li></ul><p>Completion runs asynchronously over USB / WDP, so there&#39;s a small delay (typically &lt;100 ms) before the input updates.</p><h2 id="built-ins" tabindex="-1">Built-ins <a class="header-anchor" href="#built-ins" aria-label="Permalink to &quot;Built-ins&quot;">​</a></h2><p>The widget recognises a small set of host-side built-ins that don&#39;t go over the wire:</p><ul><li><code>clear</code> (alias <code>cls</code>) — equivalent to <code>Ctrl+L</code>.</li><li><code>help</code> — list built-ins. <code>help &lt;name&gt;</code> prints details for one.</li><li><code>exit</code> — close the channel. The next command reopens it automatically.</li></ul><p>Everything else is forwarded to the device.</p><h2 id="simulator-behaviour" tabindex="-1">Simulator behaviour <a class="header-anchor" href="#simulator-behaviour" aria-label="Permalink to &quot;Simulator behaviour&quot;">​</a></h2><p>When you&#39;re connected to the <a href="./simulator">simulated stream</a>, the Shell widget drops you into an in-memory fake (<code>lib/shellSim.ts</code>) that recognises the most common commands — <code>pwd</code>, <code>ls</code>, <code>cat</code>, <code>whoami</code>, <code>uname</code> — and simulated filesystem paths under <code>/sdcard/</code>. Use it to poke around the widget without a phone.</p><h2 id="per-widget-settings" tabindex="-1">Per-widget settings <a class="header-anchor" href="#per-widget-settings" aria-label="Permalink to &quot;Per-widget settings&quot;">​</a></h2><ul><li><strong>Home directory.</strong> Override the starting <code>cd</code> when the tile mounts.</li><li><strong>Font size.</strong> Bumps the shell text without affecting the rest of the dashboard.</li></ul><p>Changes persist per-tile via <code>localStorage</code>.</p>',22))])}const y=a(c,[["render",h]]);export{w as __pageData,y as default};
